public Void visitNoOperands(Instruction instr, Integer indent) {      return null;  }  public Void visitArrayType(Instruction instr, TypeKind kind, Integer indent) {      print(" " + kind.name);      return null;  }  public Void visitBranch(Instruction instr, int offset, Integer indent) {      print((instr.getPC() + offset));      return null;  }  public Void visitConstantPoolRef(Instruction instr, int index, Integer indent) {      print("#" + index);      tab();      print("    printConstant(index);      return null;  }  public Void visitConstantPoolRefAndValue(Instruction instr, int index, int value, Integer indent) {      print("#" + index + ",  " + value);      tab();      print("    printConstant(index);      return null;  }  public Void visitLocal(Instruction instr, int index, Integer indent) {      print(index);      return null;  }  public Void visitLocalAndValue(Instruction instr, int index, int value, Integer indent) {      print(index + ", " + value);      return null;  }  public Void visitLookupSwitch(Instruction instr, int default_, int npairs, int[] matches, int[] offsets, Integer indent) {      int pc = instr.getPC();      print("{     indent(indent);      for (int i = 0; i < npairs; i++) {          print(String.format("%n%12d: %d", matches[i], (pc + offsets[i])));      }      print("
     default: " + (pc + default_) + "
}");      indent(-indent);      return null;  }  public Void visitTableSwitch(Instruction instr, int default_, int low, int high, int[] offsets, Integer indent) {      int pc = instr.getPC();      print("{     indent(indent);      for (int i = 0; i < offsets.length; i++) {          print(String.format("%n%12d: %d", (low + i), (pc + offsets[i])));      }      print("
     default: " + (pc + default_) + "
}");      indent(-indent);      return null;  }  public Void visitValue(Instruction instr, int value, Integer indent) {      print(value);      return null;  }  public Void visitUnknown(Instruction instr, Integer indent) {      return null;  }  visitLookupSwitch  visitTableSwitch

private String findPrevious(TableColumn tableColumn, Table newTable) {      int index = newTable.getColumnList().indexOf(tableColumn);      if (index == 0) {          return "-1";      }          for (int i = index - 1; i >= 0; i--) {          if (newTable.getColumnList().get(i).getEditStatus() == null || !newTable.getColumnList().get(i).getEditStatus().equals(EditStatus.DELETE.name())) {              return newTable.getColumnList().get(i).getName();          }      }      return "-1";  }  public String buildGenerateReorderColumnSql(Table oldTable, Table newTable) {      StringBuilder sql = new StringBuilder();      int n = 0;          Map<String, Integer> oldColumnIndexMap = new HashMap<>();      for (int i = 0; i < oldTable.getColumnList().size(); i++) {          oldColumnIndexMap.put(oldTable.getColumnList().get(i).getName(), i);      }      String[] oldColumnArray = oldTable.getColumnList().stream().map(TableColumn::getName).toArray(String[]::new);      String[] newColumnArray = newTable.getColumnList().stream().map(TableColumn::getName).toArray(String[]::new);      Set<String> oldColumnSet = new HashSet<>(Arrays.asList(oldColumnArray));      Set<String> newColumnSet = new HashSet<>(Arrays.asList(newColumnArray));      if (!oldColumnSet.equals(newColumnSet)) {          return "";      }      buildSql(oldColumnArray, newColumnArray, sql, oldTable, newTable, n);      return sql.toString();  }  private String[] buildSql(String[] originalArray, String[] targetArray, StringBuilder sql, Table oldTable, Table newTable, int n) {          if (!originalArray[0].equals(targetArray[0])) {          int a = findIndex(originalArray, targetArray[0]);          TableColumn column = oldTable.getColumnList().stream().filter(col -> StringUtils.equals(col.getName(), originalArray[a])).findFirst().get();          String[] newArray = moveElement(originalArray, a, 0, targetArray, new AtomicInteger(0));          sql.append(" MODIFY COLUMN ");          MysqlColumnTypeEnum typeEnum = MysqlColumnTypeEnum.getByType(column.getColumnType());          sql.append(typeEnum.buildColumn(column));          sql.append(" FIRST;
");          n++;          if (Arrays.equals(newArray, targetArray)) {              return newArray;          }          String[] resultArray = buildSql(newArray, targetArray, sql, oldTable, newTable, n);          if (Arrays.equals(resultArray, targetArray)) {              return resultArray;          }      }          int max = originalArray.length - 1;      if (!originalArray[max].equals(targetArray[max])) {          int a = findIndex(originalArray, targetArray[max]);                  TableColumn column = oldTable.getColumnList().stream().filter(col -> StringUtils.equals(col.getName(), originalArray[a])).findFirst().get();          String[] newArray = moveElement(originalArray, a, max, targetArray, new AtomicInteger(0));          if (n > 0) {              sql.append("ALTER TABLE ");              if (StringUtils.isNotBlank(oldTable.getDatabaseName())) {                  sql.append("`").append(oldTable.getDatabaseName()).append("`").append(".");              }              sql.append("`").append(oldTable.getName()).append("`").append("
");          }          sql.append(" MODIFY COLUMN ");          MysqlColumnTypeEnum typeEnum = MysqlColumnTypeEnum.getByType(column.getColumnType());          sql.append(typeEnum.buildColumn(column));          sql.append(" AFTER ");          sql.append(oldTable.getColumnList().get(max).getName());          sql.append(";
");          n++;          if (Arrays.equals(newArray, targetArray)) {              return newArray;          }          String[] resultArray = buildSql(newArray, targetArray, sql, oldTable, newTable, n);          if (Arrays.equals(resultArray, targetArray)) {              return resultArray;          }      }      for (int i = 0; i < originalArray.length; i++) {          int a = findIndex(targetArray, originalArray[i]);          if (i != a && isMoveValid(originalArray, targetArray, i, a)) {                          int finalI = i;              TableColumn column = oldTable.getColumnList().stream().filter(col -> StringUtils.equals(col.getName(), originalArray[finalI])).findFirst().get();              if (n > 0) {                  sql.append("ALTER TABLE ");                  if (StringUtils.isNotBlank(oldTable.getDatabaseName())) {                      sql.append("`").append(oldTable.getDatabaseName()).append("`").append(".");                  }                  sql.append("`").append(oldTable.getName()).append("`").append("
");              }              sql.append(" MODIFY COLUMN ");              MysqlColumnTypeEnum typeEnum = MysqlColumnTypeEnum.getByType(column.getColumnType());              sql.append(typeEnum.buildColumn(column));              sql.append(" AFTER ");              AtomicInteger continuousDataCount = new AtomicInteger(0);              String[] newArray = moveElement(originalArray, i, a, targetArray, continuousDataCount);              if (i < a) {                  sql.append(originalArray[a + continuousDataCount.get()]);              } else {                  sql.append(originalArray[a - 1]);              }              sql.append(";
");              n++;              if (Arrays.equals(newArray, targetArray)) {                  return newArray;              }              String[] resultArray = buildSql(newArray, targetArray, sql, oldTable, newTable, n);              if (Arrays.equals(resultArray, targetArray)) {                  return resultArray;              }          }      }      return null;  }  buildSql  moveElement

private String dot(MavenResolutionResult mrr) {      StringBuilder dot = new StringBuilder("digraph main {
");      Map<ResolvedGroupArtifactVersion, Integer> index = new HashMap<>();          ResolvedGroupArtifactVersion root = new ResolvedGroupArtifactVersion(null, mrr.getPom().getGroupId(), mrr.getPom().getArtifactId(), mrr.getPom().getVersion(), null);      dotLabel(dot, 0, root);      index.put(root, 0);          for (Scope scope : Scope.values()) {          if (scope.ordinal() < Scope.Compile.ordinal() || Scope.Test.ordinal() < scope.ordinal()) {              continue;          }          List<ResolvedDependency> resolvedDependencies = mrr.getDependencies().get(scope);          if (resolvedDependencies == null) {              continue;          }          for (ResolvedDependency dep : resolvedDependencies) {              if (!index.containsKey(dep.getGav())) {                  dotLabel(dot, index.size(), dep.getGav());                  index.put(dep.getGav(), index.size());              }          }      }      Set<ResolvedGroupArtifactVersion> seen = newSetFromMap(new IdentityHashMap<>());      for (Scope scope : Scope.values()) {          if (scope.ordinal() < Scope.Compile.ordinal() || Scope.Test.ordinal() < scope.ordinal()) {              continue;          }          dotEdges(dot, root, scope, mrr.getDependencies().get(scope).stream().filter(dep -> dep.isDirect() && seen.add(dep.getGav())).collect(toList()), index);      }      dot.append("}");      return dot.toString();  }  private void dotLabel(StringBuilder dot, int index, ResolvedGroupArtifactVersion gav) {      dot.append(index).append(" [label="").append(gav.getGroupId()).append(":").append(gav.getArtifactId()).append(":").append(gav.getVersion()).append(""];
");  }  private void dotEdges(StringBuilder dot, ResolvedGroupArtifactVersion head, Scope scope, List<ResolvedDependency> resolvedDependencies, Map<ResolvedGroupArtifactVersion, Integer> index) {      int headIndex = index.get(head);      for (ResolvedDependency dep : resolvedDependencies) {          dot.append(headIndex).append(" -> ").append(index.get(dep.getGav())).append(" [taillabel="").append(scope).append(""];
");          dotEdges(dot, dep.getGav(), scope, dep.getDependencies(), index);      }  }  dotEdges

private boolean stopCommentExists(@Nullable J j) {      return j != null && stopCommentExists(j.getComments());  }  private void addLeadingVariableDeclarations(Cursor cursor, J current, J.Block containingBlock, StringBuilder before, J insertionPoint) {      for (Statement statement : containingBlock.getStatements()) {          if (referToSameElement(current, statement)) {              break;          }          if (statement instanceof J.Label) {              statement = ((J.Label) statement).getStatement();          }          if (statement instanceof J.VariableDeclarations) {              before.insert(0, "
" + variable((J.VariableDeclarations) statement, true, cursor) + ";
");          } else if (statement instanceof J.If) {              J.If iff = (J.If) statement;              String condition = PatternVariables.simplifiedPatternVariableCondition(iff.getIfCondition().getTree(), insertionPoint);              if (condition != null) {                  boolean thenAlwaysCompletesAbnormally = PatternVariables.alwaysCompletesAbnormally(iff.getThenPart());                  boolean elseAlwaysCompletesAbnormally = iff.getElsePart() != null && PatternVariables.alwaysCompletesAbnormally(iff.getElsePart().getBody());                  if (thenAlwaysCompletesAbnormally || elseAlwaysCompletesAbnormally) {                      StringBuilder ifStatement = new StringBuilder("if (").append(condition).append(") {");                      ifStatement.append(thenAlwaysCompletesAbnormally ? " throw new RuntimeException(); }" : " }");                      ifStatement.append(elseAlwaysCompletesAbnormally ? " else { throw new RuntimeException(); }" : " else { }");                      before.insert(0, ifStatement);                  }              }          }      }  }  private void insertControlWithBlock(J body, StringBuilder before, StringBuilder after, Runnable insertion) {      if (!(body instanceof J.Block)) {          before.insert(0, "{");      }      insertion.run();      if (!(body instanceof J.Block)) {          after.append("}");      }  }  private void classDeclaration(@Nullable J prior, J.ClassDeclaration cd, StringBuilder before, StringBuilder after, Cursor cursor, JavaCoordinates.Mode mode) {      StringBuilder beforeBuffer = prior == null ? null : new StringBuilder();      StringBuilder appendBuffer = prior == null ? after : beforeBuffer;      appendBuffer.append(cd.withBody(null).withLeadingAnnotations(null).withPrefix(Space.EMPTY).printTrimmed(cursor).trim()).append('{');      List<Statement> statements = cd.getBody().getStatements();      for (Statement statement : statements) {          if (referToSameElement(statement, prior)) {              if (mode != AFTER) {                  appendBuffer = after;                  if (mode == REPLACEMENT) {                      continue;                  }              }          }          if (statement instanceof J.EnumValueSet) {              J.EnumValueSet enumValues = (J.EnumValueSet) statements.get(0);              StringJoiner enumStr = new StringJoiner(",");              for (J.EnumValue anEnum : enumValues.getEnums()) {                  String en = anEnum.getName().getSimpleName();                  enumStr.add(en);              }              appendBuffer.append(enumStr).append(";
");          } else if (statement instanceof J.VariableDeclarations) {              String variable = variable((J.VariableDeclarations) statement, false, cursor);              appendBuffer.append(variable).append(";
");          } else if (statement instanceof J.MethodDeclaration) {              String m = method((J.MethodDeclaration) statement, cursor);              appendBuffer.append(m);          } else if (statement instanceof J.ClassDeclaration) {                          classDeclaration(null, (J.ClassDeclaration) statement, before, appendBuffer, cursor, REPLACEMENT);              appendBuffer.append('}');          }      }      if (beforeBuffer != null) {          before.insert(0, beforeBuffer);      }  }  private String method(J.MethodDeclaration method, Cursor cursor) {      if (method.isAbstract()) {          return "
" + method.withPrefix(Space.EMPTY).printTrimmed(cursor).trim() + ";
";      }      StringBuilder methodBuilder = new StringBuilder("
");      J.MethodDeclaration m = method.withBody(null).withLeadingAnnotations(emptyList()).withPrefix(Space.EMPTY);      methodBuilder.append(m.printTrimmed(cursor).trim()).append('{');      if (method.getReturnTypeExpression() != null && JavaType.Primitive.Void != method.getReturnTypeExpression().getType()) {          methodBuilder.append("
return ").append(valueOfType(method.getReturnTypeExpression().getType())).append(";
");      }      methodBuilder.append("}
");      return methodBuilder.toString();  }  private String variable(J.VariableDeclarations variable, boolean initializer, Cursor cursor) {      StringBuilder varBuilder = new StringBuilder();      for (J.Modifier modifier : variable.getModifiers()) {          varBuilder.append(modifier.getType().toString().toLowerCase()).append(' ');      }      List<J.VariableDeclarations.NamedVariable> variables = variable.getVariables();      for (int i = 0, variablesSize = variables.size(); i < variablesSize; i++) {          J.VariableDeclarations.NamedVariable nv = variables.get(i);          if (i == 0) {              if (variable.getTypeExpression() != null) {                  varBuilder.append(variable.getTypeExpression().withPrefix(Space.EMPTY).printTrimmed(cursor));              }              if (nv.getType() instanceof JavaType.Array) {                  if (nv.getInitializer() instanceof J.NewArray && !((J.NewArray) nv.getInitializer()).getDimensions().isEmpty()) {                      J.NewArray na = (J.NewArray) nv.getInitializer();                      na.getDimensions().forEach(d -> varBuilder.append("[]"));                  } else {                      varBuilder.append("[]");                  }              }              varBuilder.append(" ");          }          varBuilder.append(nv.getSimpleName());          JavaType type = nv.getType();          if (initializer && type != null) {              varBuilder.append('=').append(valueOfType(type));          }          if (i < variables.size() - 1) {              varBuilder.append(',');          }      }      return varBuilder.toString();  }  private String valueOfType(@Nullable JavaType type) {      JavaType.Primitive primitive = TypeUtils.asPrimitive(type);      if (primitive != null) {          switch(primitive) {              case Boolean:                  return "true";              case Byte:              case Char:              case Int:              case Double:              case Float:              case Long:              case Short:                  return "0";              case String:              case Null:                  return "null";              case None:              case Void:              default:                  return "";          }      }      return "null";  }  private Cursor next(Cursor c) {      return c.getParentTreeCursor();  }  template  contextFreeTemplate  contextTemplate  addLeadingVariableDeclarations  classDeclaration

