@Test  public void testParseGeoJson() throws Exception {      JSONObject validGeoJsonObject = new JSONObject("{ "type": "MultiLineString",
" + "    "coordinates": [
" + "        [ [100.0, 0.0], [101.0, 1.0] ],
" + "        [ [102.0, 2.0], [103.0, 3.0] ]
" + "      ]
" + "    }");      GeoJsonParser parser = new GeoJsonParser(validGeoJsonObject);      GeoJsonLineString ls1 = new GeoJsonLineString(new ArrayList<>(Arrays.asList(new LatLng(0, 100), new LatLng(1, 101))));      GeoJsonLineString ls2 = new GeoJsonLineString(new ArrayList<>(Arrays.asList(new LatLng(2, 102), new LatLng(3, 103))));      GeoJsonMultiLineString geoJsonMultiLineString = new GeoJsonMultiLineString(new ArrayList<>(Arrays.asList(ls1, ls2)));      GeoJsonFeature geoJsonFeature = new GeoJsonFeature(geoJsonMultiLineString, null, null, null);      List<GeoJsonFeature> geoJsonFeatures = new ArrayList<>(Arrays.asList(geoJsonFeature));      assertEquals(geoJsonFeatures.get(0).getId(), parser.getFeatures().get(0).getId());  }  @Test  public void testParseGeometryCollection() throws Exception {      GeoJsonParser parser = new GeoJsonParser(validGeometryCollection());      assertEquals(1, parser.getFeatures().size());      for (GeoJsonFeature feature : parser.getFeatures()) {          assertEquals("GeometryCollection", feature.getGeometry().getGeometryType());          int size = 0;          for (String property : feature.getPropertyKeys()) {              size++;          }          assertEquals(2, size);          assertEquals("Popsicles", feature.getId());          GeoJsonGeometryCollection geometry = ((GeoJsonGeometryCollection) feature.getGeometry());          assertEquals(1, geometry.getGeometries().size());          for (Geometry geoJsonGeometry : geometry.getGeometries()) {              assertEquals("GeometryCollection", geoJsonGeometry.getGeometryType());          }      }  }  @Test  public void testParsePoint() throws Exception {      GeoJsonParser parser = new GeoJsonParser(validPoint());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getBoundingBox());      assertNull(parser.getFeatures().get(0).getId());      int size = 0;      for (String property : parser.getFeatures().get(0).getPropertyKeys()) {          size++;      }      assertEquals(0, size);      assertTrue(parser.getFeatures().get(0).getGeometry() instanceof GeoJsonPoint);      GeoJsonPoint point = (GeoJsonPoint) parser.getFeatures().get(0).getGeometry();      assertEquals(new LatLng(0.0, 100.0), point.getCoordinates());  }  @Test  public void testParseLineString() throws Exception {      GeoJsonParser parser = new GeoJsonParser(validLineString());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getBoundingBox());      assertNull(parser.getFeatures().get(0).getId());      int size = 0;      for (String property : parser.getFeatures().get(0).getPropertyKeys()) {          size++;      }      assertEquals(0, size);      assertTrue(parser.getFeatures().get(0).getGeometry() instanceof GeoJsonLineString);      GeoJsonLineString lineString = (GeoJsonLineString) parser.getFeatures().get(0).getGeometry();      assertEquals(2, lineString.getCoordinates().size());      List<LatLng> ls = new ArrayList<>(Arrays.asList(new LatLng(0, 100), new LatLng(1, 101)));      assertEquals(ls, lineString.getCoordinates());  }  @Test  public void testParsePolygon() throws Exception {      GeoJsonParser parser = new GeoJsonParser(validPolygon());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getBoundingBox());      assertNull(parser.getFeatures().get(0).getId());      int size = 0;      for (String property : parser.getFeatures().get(0).getPropertyKeys()) {          size++;      }      assertEquals(0, size);      assertTrue(parser.getFeatures().get(0).getGeometry() instanceof GeoJsonPolygon);      GeoJsonPolygon polygon = (GeoJsonPolygon) parser.getFeatures().get(0).getGeometry();      assertEquals(2, polygon.getCoordinates().size());      assertEquals(5, polygon.getCoordinates().get(0).size());      assertEquals(5, polygon.getCoordinates().get(1).size());      List<ArrayList<LatLng>> p = new ArrayList<>();      p.add(new ArrayList<>(Arrays.asList(new LatLng(0, 100), new LatLng(0, 101), new LatLng(1, 101), new LatLng(1, 100), new LatLng(0, 100))));      p.add(new ArrayList<>(Arrays.asList(new LatLng(0.2, 100.2), new LatLng(0.2, 100.8), new LatLng(0.8, 100.8), new LatLng(0.8, 100.2), new LatLng(0.2, 100.2))));      assertEquals(p, polygon.getCoordinates());  }  @Test  public void testParseMultiPoint() throws Exception {      GeoJsonParser parser = new GeoJsonParser(validMultiPoint());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getBoundingBox());      assertNull(parser.getFeatures().get(0).getId());      int size = 0;      for (String property : parser.getFeatures().get(0).getPropertyKeys()) {          size++;      }      assertEquals(0, size);      assertTrue(parser.getFeatures().get(0).getGeometry() instanceof GeoJsonMultiPoint);      GeoJsonMultiPoint multiPoint = (GeoJsonMultiPoint) parser.getFeatures().get(0).getGeometry();      assertEquals(2, multiPoint.getPoints().size());      assertEquals(new LatLng(0, 100), multiPoint.getPoints().get(0).getCoordinates());      assertEquals(new LatLng(1, 101), multiPoint.getPoints().get(1).getCoordinates());  }  @Test  public void testParseMultiLineString() throws Exception {      GeoJsonParser parser = new GeoJsonParser(validMultiLineString());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getBoundingBox());      assertNull(parser.getFeatures().get(0).getId());      int size = 0;      for (String property : parser.getFeatures().get(0).getPropertyKeys()) {          size++;      }      assertEquals(0, size);      assertTrue(parser.getFeatures().get(0).getGeometry() instanceof GeoJsonMultiLineString);      GeoJsonMultiLineString multiLineString = (GeoJsonMultiLineString) parser.getFeatures().get(0).getGeometry();      assertEquals(2, multiLineString.getLineStrings().size());      List<LatLng> ls = new ArrayList<>(Arrays.asList(new LatLng(0, 100), new LatLng(1, 101)));      assertEquals(ls, multiLineString.getLineStrings().get(0).getCoordinates());      ls = new ArrayList<>(Arrays.asList(new LatLng(2, 102), new LatLng(3, 103)));      assertEquals(ls, multiLineString.getLineStrings().get(1).getCoordinates());  }  @Test  public void testParseMultiPolygon() throws Exception {      GeoJsonParser parser = new GeoJsonParser(validMultiPolygon());      assertEquals(1, parser.getFeatures().size());      GeoJsonFeature feature = parser.getFeatures().get(0);      GeoJsonMultiPolygon polygon = ((GeoJsonMultiPolygon) feature.getGeometry());      assertEquals(2, polygon.getPolygons().size());      assertEquals(1, polygon.getPolygons().get(0).getCoordinates().size());      List<List<LatLng>> p1 = new ArrayList<>();      p1.add(new ArrayList<>(Arrays.asList(new LatLng(2, 102), new LatLng(2, 103), new LatLng(3, 103), new LatLng(3, 102), new LatLng(2, 102))));      assertEquals(p1, polygon.getPolygons().get(0).getCoordinates());      assertEquals(2, polygon.getPolygons().get(1).getCoordinates().size());      List<List<LatLng>> p2 = new ArrayList<>();      p2.add(new ArrayList<>(Arrays.asList(new LatLng(0, 100), new LatLng(0, 101), new LatLng(1, 101), new LatLng(1, 100), new LatLng(0, 100))));      p2.add(new ArrayList<>(Arrays.asList(new LatLng(0.2, 100.2), new LatLng(0.2, 100.8), new LatLng(0.8, 100.8), new LatLng(0.8, 100.2), new LatLng(0.2, 100.2))));      assertEquals(p2, polygon.getPolygons().get(1).getCoordinates());  }  @Test  public void testEmptyFile() {      GeoJsonParser parser = new GeoJsonParser(emptyFile());      assertNull(parser.getBoundingBox());      assertEquals(0, parser.getFeatures().size());  }  @Test  public void testInvalidFeature() throws Exception {      GeoJsonParser parser;          parser = new GeoJsonParser(invalidFeatureNoGeometry());      assertNull(parser.getBoundingBox());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getGeometry());      assertEquals("Dinagat Islands", parser.getFeatures().get(0).getProperty("name"));          parser = new GeoJsonParser(invalidFeatureNoProperties());      assertNull(parser.getBoundingBox());      assertEquals(1, parser.getFeatures().size());      int size = 0;      for (String property : parser.getFeatures().get(0).getPropertyKeys()) {          size++;      }      assertEquals(0, size);          parser = new GeoJsonParser(invalidFeatureMissingType());      assertNull(parser.getBoundingBox());      assertEquals(0, parser.getFeatures().size());          parser = new GeoJsonParser(invalidFeatureGeometryCollectionInvalidGeometry());      assertNull(parser.getBoundingBox());      assertEquals(1, parser.getFeatures().size());      assertEquals(1, ((GeoJsonGeometryCollection) parser.getFeatures().get(0).getGeometry()).getGeometries().size());          parser = new GeoJsonParser(invalidFeatureGeometryCollectionNoGeometries());      assertNull(parser.getBoundingBox());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getGeometry());  }  @Test  public void testInvalidFeatureCollection() throws Exception {      GeoJsonParser parser;          parser = new GeoJsonParser(invalidFeatureCollectionNoCoordinatesInGeometryInFeature());      assertNull(parser.getBoundingBox());      assertEquals(3, parser.getFeatures().size());      assertNotNull(parser.getFeatures().get(0).getGeometry());      assertNull(parser.getFeatures().get(1).getGeometry());      assertNotNull(parser.getFeatures().get(2).getGeometry());          parser = new GeoJsonParser(invalidFeatureCollectionNoTypeInGeometryInFeature());      assertNull(parser.getBoundingBox());      assertEquals(3, parser.getFeatures().size());      assertNotNull(parser.getFeatures().get(0).getGeometry());      assertNotNull(parser.getFeatures().get(1).getGeometry());      assertNull(parser.getFeatures().get(2).getGeometry());          parser = new GeoJsonParser(invalidFeatureCollectionNoFeaturesArray());      assertNull(parser.getBoundingBox());      assertEquals(0, parser.getFeatures().size());          parser = new GeoJsonParser(invalidFeatureCollectionNoGeometryTypeInFeature());      assertNull(parser.getBoundingBox());      assertEquals(2, parser.getFeatures().size());      assertTrue(!parser.getFeatures().get(0).getGeometry().getGeometryType().equals("Polygon") && !parser.getFeatures().get(1).getGeometry().getGeometryType().equals("Polygon"));          parser = new GeoJsonParser(invalidFeatureNoCoordinatesInGeometry());      assertNull(parser.getBoundingBox());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getGeometry());  }  @Test  public void testInvalidGeometry() throws Exception {      GeoJsonParser parser;          parser = new GeoJsonParser(invalidGeometryNoType());      assertNull(parser.getBoundingBox());      assertEquals(0, parser.getFeatures().size());          parser = new GeoJsonParser(invalidGeometryNoCoordinates());      assertNull(parser.getBoundingBox());      assertEquals(0, parser.getFeatures().size());          parser = new GeoJsonParser(invalidGeometryCollectionInvalidGeometry());      assertNull(parser.getBoundingBox());      assertEquals(1, parser.getFeatures().size());      assertEquals(1, ((GeoJsonGeometryCollection) parser.getFeatures().get(0).getGeometry()).getGeometries().size());          parser = new GeoJsonParser(invalidGeometryCollectionInvalidGeometries());      assertNull(parser.getBoundingBox());      assertEquals(0, parser.getFeatures().size());          parser = new GeoJsonParser(invalidGeometryInvalidCoordinatesPair());      assertEquals(0, parser.getFeatures().size());          parser = new GeoJsonParser(invalidGeometryInvalidCoordinatesString());      assertEquals(0, parser.getFeatures().size());  }

