@Override  protected void onCreate(@Nullable Bundle savedInstanceState) {      super.onCreate(savedInstanceState);      setContentView(R.layout.activity_picker_calendar);      Date minDate = new Date(System.currentTimeMillis() - 5 * android.text.format.DateUtils.DAY_IN_MILLIS);      Calendar calendar = DateUtils.calendar(minDate);      calendar.add(Calendar.MONTH, 3);      Date maxDate = calendar.getTime();      CalendarView horizontalCalendarView = findViewById(R.id.calendar_picker_body_horizontal);      horizontalCalendarView.enablePagerSnap();      horizontalCalendarView.getAdapter().notify(false).single(false).festivalProvider(new MyFestivalProvider()).valid(minDate, maxDate).intervalNotes("开始", "结束").select(minDate.getTime(), minDate.getTime() + 5 * android.text.format.DateUtils.DAY_IN_MILLIS).range(minDate, maxDate).refresh();      CalendarView verticalCalendarView = findViewById(R.id.calendar_picker_body_vertical);      verticalCalendarView.getAdapter().notify(false).single(false).festivalProvider(new MyFestivalProvider()).valid(minDate, maxDate).intervalNotes("开始", "结束").select(minDate.getTime(), minDate.getTime() + 5 * android.text.format.DateUtils.DAY_IN_MILLIS).range(minDate, maxDate).refresh();  }  @Override  public void onRangeDatePicked(@NonNull Date startDate, @NonNull Date endDate) {      startTimeInMillis = startDate.getTime();      endTimeInMillis = endDate.getTime();      Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(startDate) + "
" + DateFormat.getDateTimeInstance().format(endDate), Toast.LENGTH_SHORT).show();  }  @Override  public void onMonthChanged(Date date) {      Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(date), Toast.LENGTH_SHORT).show();  }  public void onCalendarColorScheme(View view) {      CalendarPicker picker = new CalendarPicker(this);      Date currentDate = new Date(System.currentTimeMillis());      if (startTimeInMillis == 0 && endTimeInMillis == 0) {          startTimeInMillis = currentDate.getTime() - 3 * android.text.format.DateUtils.DAY_IN_MILLIS;          endTimeInMillis = currentDate.getTime() + 3 * android.text.format.DateUtils.DAY_IN_MILLIS;      }      picker.setSelectedDate(startTimeInMillis, endTimeInMillis);      picker.setColorScheme(new ColorScheme().daySelectBackgroundColor(0xFF00CC00).dayStressTextColor(0xFF00AA00));      picker.setOnRangeDatePickListener(new OnRangeDatePickListener() {            @Override          public void onRangeDatePicked(@NonNull Date startDate, @NonNull Date endDate) {              startTimeInMillis = startDate.getTime();              endTimeInMillis = endDate.getTime();              Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(startDate) + "
" + DateFormat.getDateTimeInstance().format(endDate), Toast.LENGTH_SHORT).show();          }            @Override          public void onMonthChanged(Date date) {              Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(date), Toast.LENGTH_SHORT).show();          }      });      picker.show();  }  @Override  public void onRangeDatePicked(@NonNull Date startDate, @NonNull Date endDate) {      startTimeInMillis = startDate.getTime();      endTimeInMillis = endDate.getTime();      Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(startDate) + "
" + DateFormat.getDateTimeInstance().format(endDate), Toast.LENGTH_SHORT).show();  }  @Override  public void onMonthChanged(Date date) {      Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(date), Toast.LENGTH_SHORT).show();  }  public void onCalendarDateRange(View view) {      CalendarPicker picker = new CalendarPicker(this);      Date currentDate = new Date(System.currentTimeMillis());      Calendar minCalendar = DateUtils.calendar(currentDate);      minCalendar.add(Calendar.MONTH, -12);      minCalendar.set(Calendar.DAY_OF_MONTH, DateUtils.maxDaysOfMonth(minCalendar.getTime()));      Date minDate = minCalendar.getTime();      Calendar maxCalendar = DateUtils.calendar(currentDate);      maxCalendar.setTime(currentDate);      maxCalendar.add(Calendar.MONTH, 12);      maxCalendar.set(Calendar.DAY_OF_MONTH, DateUtils.maxDaysOfMonth(maxCalendar.getTime()));      Date maxDate = maxCalendar.getTime();      picker.setRangeDate(minDate, maxDate);      if (startTimeInMillis == 0 && endTimeInMillis == 0) {          startTimeInMillis = currentDate.getTime() - 3 * android.text.format.DateUtils.DAY_IN_MILLIS;          endTimeInMillis = currentDate.getTime() + 3 * android.text.format.DateUtils.DAY_IN_MILLIS;      }      picker.setSelectedDate(startTimeInMillis, endTimeInMillis);      picker.setOnRangeDatePickListener(new OnRangeDatePickListener() {            @Override          public void onRangeDatePicked(@NonNull Date startDate, @NonNull Date endDate) {              startTimeInMillis = startDate.getTime();              endTimeInMillis = endDate.getTime();              Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(startDate) + "
" + DateFormat.getDateTimeInstance().format(endDate), Toast.LENGTH_SHORT).show();          }            @Override          public void onMonthChanged(Date date) {              Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(date), Toast.LENGTH_SHORT).show();          }      });      picker.show();  }  @Override  public void onSingleDatePicked(@NonNull Date date) {      singleTimeInMillis = date.getTime();      Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(date), Toast.LENGTH_SHORT).show();  }  @Override  public void onMonthChanged(Date date) {      Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(date), Toast.LENGTH_SHORT).show();  }  public void onCalendarDateSingle(View view) {      CalendarPicker picker = new CalendarPicker(this);      picker.setRangeDateOnFuture(3);      if (singleTimeInMillis == 0) {          singleTimeInMillis = System.currentTimeMillis();      }      picker.setSelectedDate(singleTimeInMillis);      picker.setFestivalProvider(new MyFestivalProvider());      picker.setOnSingleDatePickListener(new OnSingleDatePickListener() {            @Override          public void onSingleDatePicked(@NonNull Date date) {              singleTimeInMillis = date.getTime();              Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(date), Toast.LENGTH_SHORT).show();          }            @Override          public void onMonthChanged(Date date) {              Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(date), Toast.LENGTH_SHORT).show();          }      });      picker.show();  }  @Override  public void onSingleDatePicked(@NonNull Date date) {      singleTimeInMillis = date.getTime();      Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(date), Toast.LENGTH_SHORT).show();  }  @Override  public void onMonthChanged(Date date) {      Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(date), Toast.LENGTH_SHORT).show();  }  public void onHorizontalCalendarPicker(View view) {      CalendarPicker picker = new CalendarPicker(this);      picker.enablePagerSnap();      picker.setRangeDateOnFuture(3);      picker.setFestivalProvider(new MyFestivalProvider());      picker.setOnSingleDatePickListener(new OnSingleDatePickListener() {            @Override          public void onSingleDatePicked(@NonNull Date date) {              singleTimeInMillis = date.getTime();              Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(date), Toast.LENGTH_SHORT).show();          }            @Override          public void onMonthChanged(Date date) {              Toast.makeText(getApplicationContext(), DateFormat.getDateTimeInstance().format(date), Toast.LENGTH_SHORT).show();          }      });      picker.show();  }

@Test  public void testGetId() {      GeoJsonFeature feature = new GeoJsonFeature(null, "Pirate", null, null);      assertNotNull(feature.getId());      assertEquals("Pirate", feature.getId());      feature = new GeoJsonFeature(null, null, null, null);      assertNull(feature.getId());  }  @Test  public void testProperty() {      HashMap<String, String> properties = new HashMap<>();      properties.put("Color", "Yellow");      properties.put("Width", "5");      GeoJsonFeature feature = new GeoJsonFeature(null, null, properties, null);      assertFalse(feature.hasProperty("llama"));      assertTrue(feature.hasProperty("Color"));      assertEquals("Yellow", feature.getProperty("Color"));      assertTrue(feature.hasProperty("Width"));      assertEquals("5", feature.getProperty("Width"));      assertNull(feature.removeProperty("banana"));      assertEquals("5", feature.removeProperty("Width"));      assertNull(feature.setProperty("Width", "10"));      assertEquals("10", feature.setProperty("Width", "500"));  }  @Test  public void testNullProperty() {      GeoJsonLayer layer = new GeoJsonLayer(null, createFeatureCollection());      GeoJsonFeature feature = layer.getFeatures().iterator().next();      assertTrue(feature.hasProperty("prop0"));      assertNull(feature.getProperty("prop0"));      assertFalse(feature.hasProperty("prop1"));      assertNull(feature.getProperty("prop1"));  }  @Test  public void testPointStyle() {      GeoJsonFeature feature = new GeoJsonFeature(null, null, null, null);      GeoJsonPointStyle pointStyle = new GeoJsonPointStyle();      feature.setPointStyle(pointStyle);      assertEquals(pointStyle, feature.getPointStyle());      try {          feature.setPointStyle(null);          fail();      } catch (IllegalArgumentException e) {          assertEquals("Point style cannot be null", e.getMessage());      }  }  @Test  public void testLineStringStyle() {      GeoJsonFeature feature = new GeoJsonFeature(null, null, null, null);      GeoJsonLineStringStyle lineStringStyle = new GeoJsonLineStringStyle();      feature.setLineStringStyle(lineStringStyle);      assertEquals(lineStringStyle, feature.getLineStringStyle());      try {          feature.setLineStringStyle(null);          fail();      } catch (IllegalArgumentException e) {          assertEquals("Line string style cannot be null", e.getMessage());      }  }  @Test  public void testPolygonStyle() {      GeoJsonFeature feature = new GeoJsonFeature(null, null, null, null);      GeoJsonPolygonStyle polygonStyle = new GeoJsonPolygonStyle();      feature.setPolygonStyle(polygonStyle);      assertEquals(polygonStyle, feature.getPolygonStyle());      try {          feature.setPolygonStyle(null);          fail();      } catch (IllegalArgumentException e) {          assertEquals("Polygon style cannot be null", e.getMessage());      }  }  @Test  public void testGeometry() {      GeoJsonFeature feature = new GeoJsonFeature(null, null, null, null);      assertNull(feature.getGeometry());      GeoJsonPoint point = new GeoJsonPoint(new LatLng(0, 0));      feature.setGeometry(point);      assertEquals(point, feature.getGeometry());      feature.setGeometry(null);      assertNull(feature.getGeometry());      GeoJsonLineString lineString = new GeoJsonLineString(new ArrayList<>(Arrays.asList(new LatLng(0, 0), new LatLng(50, 50))));      feature = new GeoJsonFeature(lineString, null, null, null);      assertEquals(lineString, feature.getGeometry());      feature.setGeometry(point);      assertEquals(point, feature.getGeometry());      feature.setGeometry(null);      assertNull(feature.getGeometry());      feature.setGeometry(lineString);      assertEquals(lineString, feature.getGeometry());  }  @Test  public void testGetBoundingBox() {      GeoJsonFeature feature = new GeoJsonFeature(null, null, null, null);      assertNull(feature.getBoundingBox());      LatLngBounds boundingBox = new LatLngBounds(new LatLng(-20, -20), new LatLng(50, 50));      feature = new GeoJsonFeature(null, null, null, boundingBox);      assertEquals(boundingBox, feature.getBoundingBox());  }  private JSONObject createFeatureCollection() {      try {          return new JSONObject("{ "type": "FeatureCollection",
" + ""bbox": [-150.0, -80.0, 150.0, 80.0],    "features": [
" + "      { "type": "Feature",
" + "        "id": "point", 
" + "        "geometry": {"type": "Point", "coordinates": [102.0," + " 0.5]},
" + "        "properties": {"prop0": null}
" + "        }
" + "       ]
" + "     }");      } catch (JSONException e) {          fail();      }      return null;  }

@Before  public void setUp() throws Exception {      mLayer = new GeoJsonLayer(map, createFeatureCollection());  }  @Test  public void testGetFeatures() {      int featureCount = 0;      for (Feature ignored : mLayer.getFeatures()) {          featureCount++;      }      assertEquals(3, featureCount);  }  @Test  public void testAddFeature() {      int featureCount = 0;      mLayer.addFeature(new GeoJsonFeature(null, null, null, null));      for (Feature ignored : mLayer.getFeatures()) {          featureCount++;      }      assertEquals(4, featureCount);  }  @Test  public void testRemoveFeature() {      int featureCount = 0;      for (Feature ignored : mLayer.getFeatures()) {          featureCount++;      }      assertEquals(3, featureCount);  }  @Test  public void testMap() {      assertEquals(map, mLayer.getMap());      mLayer.setMap(map2);      assertEquals(map2, mLayer.getMap());      mLayer.setMap(null);      assertNull(mLayer.getMap());  }  @Test  public void testDefaultPointStyle() {      mLayer.getDefaultPointStyle().setTitle("Dolphin");      assertEquals("Dolphin", mLayer.getDefaultPointStyle().getTitle());  }  @Test  public void testDefaultLineStringStyle() {      mLayer.getDefaultLineStringStyle().setColor(Color.BLUE);      assertEquals(Color.BLUE, mLayer.getDefaultLineStringStyle().getColor());  }  @Test  public void testDefaultPolygonStyle() {      mLayer.getDefaultPolygonStyle().setGeodesic(true);      assertTrue(mLayer.getDefaultPolygonStyle().isGeodesic());  }  @Test  public void testGetBoundingBox() {      assertEquals(new LatLngBounds(new LatLng(-80, -150), new LatLng(80, 150)), mLayer.getBoundingBox());  }  private JSONObject createFeatureCollection() throws Exception {      return new JSONObject("{ "type": "FeatureCollection",
" + ""bbox": [-150.0, -80.0, 150.0, 80.0],    "features": [
" + "      { "type": "Feature",
" + "        "id": "point", 
" + "        "geometry": {"type": "Point", "coordinates": [102.0," + " 0.5]},
" + "        "properties": {"prop0": "value0"}
" + "        },
" + "      { "type": "Feature",
" + "        "geometry": {
" + "          "type": "LineString",
" + "          "coordinates": [
" + "            [102.0, 0.0], [103.0, 1.0], [104.0, 0.0], [105.0, 1.0]
" + "            ]
" + "          },
" + "        "properties": {
" + "          "prop0": "value0",
" + "          "prop1": 0.0
" + "          }
" + "        },
" + "      { "type": "Feature",
" + "         "geometry": {
" + "           "type": "Polygon",
" + "           "coordinates": [
" + "             [ [100.0, 0.0], [101.0, 0.0], [101.0, 1.0],
" + "               [100.0, 1.0], [100.0, 0.0] ]
" + "             ]
" + "         },
" + "         "properties": {
" + "           "prop0": "value0",
" + "           "prop1": {"this": "that"}
" + "           }
" + "         }
" + "       ]
" + "     }");  }

@Test  public void testParseGeoJson() throws Exception {      JSONObject validGeoJsonObject = new JSONObject("{ "type": "MultiLineString",
" + "    "coordinates": [
" + "        [ [100.0, 0.0], [101.0, 1.0] ],
" + "        [ [102.0, 2.0], [103.0, 3.0] ]
" + "      ]
" + "    }");      GeoJsonParser parser = new GeoJsonParser(validGeoJsonObject);      GeoJsonLineString ls1 = new GeoJsonLineString(new ArrayList<>(Arrays.asList(new LatLng(0, 100), new LatLng(1, 101))));      GeoJsonLineString ls2 = new GeoJsonLineString(new ArrayList<>(Arrays.asList(new LatLng(2, 102), new LatLng(3, 103))));      GeoJsonMultiLineString geoJsonMultiLineString = new GeoJsonMultiLineString(new ArrayList<>(Arrays.asList(ls1, ls2)));      GeoJsonFeature geoJsonFeature = new GeoJsonFeature(geoJsonMultiLineString, null, null, null);      List<GeoJsonFeature> geoJsonFeatures = new ArrayList<>(Arrays.asList(geoJsonFeature));      assertEquals(geoJsonFeatures.get(0).getId(), parser.getFeatures().get(0).getId());  }  @Test  public void testParseGeometryCollection() throws Exception {      GeoJsonParser parser = new GeoJsonParser(validGeometryCollection());      assertEquals(1, parser.getFeatures().size());      for (GeoJsonFeature feature : parser.getFeatures()) {          assertEquals("GeometryCollection", feature.getGeometry().getGeometryType());          int size = 0;          for (String property : feature.getPropertyKeys()) {              size++;          }          assertEquals(2, size);          assertEquals("Popsicles", feature.getId());          GeoJsonGeometryCollection geometry = ((GeoJsonGeometryCollection) feature.getGeometry());          assertEquals(1, geometry.getGeometries().size());          for (Geometry geoJsonGeometry : geometry.getGeometries()) {              assertEquals("GeometryCollection", geoJsonGeometry.getGeometryType());          }      }  }  @Test  public void testParsePoint() throws Exception {      GeoJsonParser parser = new GeoJsonParser(validPoint());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getBoundingBox());      assertNull(parser.getFeatures().get(0).getId());      int size = 0;      for (String property : parser.getFeatures().get(0).getPropertyKeys()) {          size++;      }      assertEquals(0, size);      assertTrue(parser.getFeatures().get(0).getGeometry() instanceof GeoJsonPoint);      GeoJsonPoint point = (GeoJsonPoint) parser.getFeatures().get(0).getGeometry();      assertEquals(new LatLng(0.0, 100.0), point.getCoordinates());  }  @Test  public void testParseLineString() throws Exception {      GeoJsonParser parser = new GeoJsonParser(validLineString());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getBoundingBox());      assertNull(parser.getFeatures().get(0).getId());      int size = 0;      for (String property : parser.getFeatures().get(0).getPropertyKeys()) {          size++;      }      assertEquals(0, size);      assertTrue(parser.getFeatures().get(0).getGeometry() instanceof GeoJsonLineString);      GeoJsonLineString lineString = (GeoJsonLineString) parser.getFeatures().get(0).getGeometry();      assertEquals(2, lineString.getCoordinates().size());      List<LatLng> ls = new ArrayList<>(Arrays.asList(new LatLng(0, 100), new LatLng(1, 101)));      assertEquals(ls, lineString.getCoordinates());  }  @Test  public void testParsePolygon() throws Exception {      GeoJsonParser parser = new GeoJsonParser(validPolygon());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getBoundingBox());      assertNull(parser.getFeatures().get(0).getId());      int size = 0;      for (String property : parser.getFeatures().get(0).getPropertyKeys()) {          size++;      }      assertEquals(0, size);      assertTrue(parser.getFeatures().get(0).getGeometry() instanceof GeoJsonPolygon);      GeoJsonPolygon polygon = (GeoJsonPolygon) parser.getFeatures().get(0).getGeometry();      assertEquals(2, polygon.getCoordinates().size());      assertEquals(5, polygon.getCoordinates().get(0).size());      assertEquals(5, polygon.getCoordinates().get(1).size());      List<ArrayList<LatLng>> p = new ArrayList<>();      p.add(new ArrayList<>(Arrays.asList(new LatLng(0, 100), new LatLng(0, 101), new LatLng(1, 101), new LatLng(1, 100), new LatLng(0, 100))));      p.add(new ArrayList<>(Arrays.asList(new LatLng(0.2, 100.2), new LatLng(0.2, 100.8), new LatLng(0.8, 100.8), new LatLng(0.8, 100.2), new LatLng(0.2, 100.2))));      assertEquals(p, polygon.getCoordinates());  }  @Test  public void testParseMultiPoint() throws Exception {      GeoJsonParser parser = new GeoJsonParser(validMultiPoint());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getBoundingBox());      assertNull(parser.getFeatures().get(0).getId());      int size = 0;      for (String property : parser.getFeatures().get(0).getPropertyKeys()) {          size++;      }      assertEquals(0, size);      assertTrue(parser.getFeatures().get(0).getGeometry() instanceof GeoJsonMultiPoint);      GeoJsonMultiPoint multiPoint = (GeoJsonMultiPoint) parser.getFeatures().get(0).getGeometry();      assertEquals(2, multiPoint.getPoints().size());      assertEquals(new LatLng(0, 100), multiPoint.getPoints().get(0).getCoordinates());      assertEquals(new LatLng(1, 101), multiPoint.getPoints().get(1).getCoordinates());  }  @Test  public void testParseMultiLineString() throws Exception {      GeoJsonParser parser = new GeoJsonParser(validMultiLineString());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getBoundingBox());      assertNull(parser.getFeatures().get(0).getId());      int size = 0;      for (String property : parser.getFeatures().get(0).getPropertyKeys()) {          size++;      }      assertEquals(0, size);      assertTrue(parser.getFeatures().get(0).getGeometry() instanceof GeoJsonMultiLineString);      GeoJsonMultiLineString multiLineString = (GeoJsonMultiLineString) parser.getFeatures().get(0).getGeometry();      assertEquals(2, multiLineString.getLineStrings().size());      List<LatLng> ls = new ArrayList<>(Arrays.asList(new LatLng(0, 100), new LatLng(1, 101)));      assertEquals(ls, multiLineString.getLineStrings().get(0).getCoordinates());      ls = new ArrayList<>(Arrays.asList(new LatLng(2, 102), new LatLng(3, 103)));      assertEquals(ls, multiLineString.getLineStrings().get(1).getCoordinates());  }  @Test  public void testParseMultiPolygon() throws Exception {      GeoJsonParser parser = new GeoJsonParser(validMultiPolygon());      assertEquals(1, parser.getFeatures().size());      GeoJsonFeature feature = parser.getFeatures().get(0);      GeoJsonMultiPolygon polygon = ((GeoJsonMultiPolygon) feature.getGeometry());      assertEquals(2, polygon.getPolygons().size());      assertEquals(1, polygon.getPolygons().get(0).getCoordinates().size());      List<List<LatLng>> p1 = new ArrayList<>();      p1.add(new ArrayList<>(Arrays.asList(new LatLng(2, 102), new LatLng(2, 103), new LatLng(3, 103), new LatLng(3, 102), new LatLng(2, 102))));      assertEquals(p1, polygon.getPolygons().get(0).getCoordinates());      assertEquals(2, polygon.getPolygons().get(1).getCoordinates().size());      List<List<LatLng>> p2 = new ArrayList<>();      p2.add(new ArrayList<>(Arrays.asList(new LatLng(0, 100), new LatLng(0, 101), new LatLng(1, 101), new LatLng(1, 100), new LatLng(0, 100))));      p2.add(new ArrayList<>(Arrays.asList(new LatLng(0.2, 100.2), new LatLng(0.2, 100.8), new LatLng(0.8, 100.8), new LatLng(0.8, 100.2), new LatLng(0.2, 100.2))));      assertEquals(p2, polygon.getPolygons().get(1).getCoordinates());  }  @Test  public void testEmptyFile() {      GeoJsonParser parser = new GeoJsonParser(emptyFile());      assertNull(parser.getBoundingBox());      assertEquals(0, parser.getFeatures().size());  }  @Test  public void testInvalidFeature() throws Exception {      GeoJsonParser parser;          parser = new GeoJsonParser(invalidFeatureNoGeometry());      assertNull(parser.getBoundingBox());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getGeometry());      assertEquals("Dinagat Islands", parser.getFeatures().get(0).getProperty("name"));          parser = new GeoJsonParser(invalidFeatureNoProperties());      assertNull(parser.getBoundingBox());      assertEquals(1, parser.getFeatures().size());      int size = 0;      for (String property : parser.getFeatures().get(0).getPropertyKeys()) {          size++;      }      assertEquals(0, size);          parser = new GeoJsonParser(invalidFeatureMissingType());      assertNull(parser.getBoundingBox());      assertEquals(0, parser.getFeatures().size());          parser = new GeoJsonParser(invalidFeatureGeometryCollectionInvalidGeometry());      assertNull(parser.getBoundingBox());      assertEquals(1, parser.getFeatures().size());      assertEquals(1, ((GeoJsonGeometryCollection) parser.getFeatures().get(0).getGeometry()).getGeometries().size());          parser = new GeoJsonParser(invalidFeatureGeometryCollectionNoGeometries());      assertNull(parser.getBoundingBox());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getGeometry());  }  @Test  public void testInvalidFeatureCollection() throws Exception {      GeoJsonParser parser;          parser = new GeoJsonParser(invalidFeatureCollectionNoCoordinatesInGeometryInFeature());      assertNull(parser.getBoundingBox());      assertEquals(3, parser.getFeatures().size());      assertNotNull(parser.getFeatures().get(0).getGeometry());      assertNull(parser.getFeatures().get(1).getGeometry());      assertNotNull(parser.getFeatures().get(2).getGeometry());          parser = new GeoJsonParser(invalidFeatureCollectionNoTypeInGeometryInFeature());      assertNull(parser.getBoundingBox());      assertEquals(3, parser.getFeatures().size());      assertNotNull(parser.getFeatures().get(0).getGeometry());      assertNotNull(parser.getFeatures().get(1).getGeometry());      assertNull(parser.getFeatures().get(2).getGeometry());          parser = new GeoJsonParser(invalidFeatureCollectionNoFeaturesArray());      assertNull(parser.getBoundingBox());      assertEquals(0, parser.getFeatures().size());          parser = new GeoJsonParser(invalidFeatureCollectionNoGeometryTypeInFeature());      assertNull(parser.getBoundingBox());      assertEquals(2, parser.getFeatures().size());      assertTrue(!parser.getFeatures().get(0).getGeometry().getGeometryType().equals("Polygon") && !parser.getFeatures().get(1).getGeometry().getGeometryType().equals("Polygon"));          parser = new GeoJsonParser(invalidFeatureNoCoordinatesInGeometry());      assertNull(parser.getBoundingBox());      assertEquals(1, parser.getFeatures().size());      assertNull(parser.getFeatures().get(0).getGeometry());  }  @Test  public void testInvalidGeometry() throws Exception {      GeoJsonParser parser;          parser = new GeoJsonParser(invalidGeometryNoType());      assertNull(parser.getBoundingBox());      assertEquals(0, parser.getFeatures().size());          parser = new GeoJsonParser(invalidGeometryNoCoordinates());      assertNull(parser.getBoundingBox());      assertEquals(0, parser.getFeatures().size());          parser = new GeoJsonParser(invalidGeometryCollectionInvalidGeometry());      assertNull(parser.getBoundingBox());      assertEquals(1, parser.getFeatures().size());      assertEquals(1, ((GeoJsonGeometryCollection) parser.getFeatures().get(0).getGeometry()).getGeometries().size());          parser = new GeoJsonParser(invalidGeometryCollectionInvalidGeometries());      assertNull(parser.getBoundingBox());      assertEquals(0, parser.getFeatures().size());          parser = new GeoJsonParser(invalidGeometryInvalidCoordinatesPair());      assertEquals(0, parser.getFeatures().size());          parser = new GeoJsonParser(invalidGeometryInvalidCoordinatesString());      assertEquals(0, parser.getFeatures().size());  }

Method Ignoring Method  @Override  public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment env) {      Messager messager = processingEnv.getMessager();      try {          String index = processingEnv.getOptions().get(OPTION_EVENT_BUS_INDEX);          if (index == null) {              messager.printMessage(Diagnostic.Kind.ERROR, "No option " + OPTION_EVENT_BUS_INDEX + " passed to annotation processor");              return false;          }          verbose = Boolean.parseBoolean(processingEnv.getOptions().get(OPTION_VERBOSE));          int lastPeriod = index.lastIndexOf('.');          String indexPackage = lastPeriod != -1 ? index.substring(0, lastPeriod) : null;          round++;          if (verbose) {              messager.printMessage(Diagnostic.Kind.NOTE, "Processing round " + round + ", new annotations: " + !annotations.isEmpty() + ", processingOver: " + env.processingOver());          }          if (env.processingOver()) {              if (!annotations.isEmpty()) {                  messager.printMessage(Diagnostic.Kind.ERROR, "Unexpected processing state: annotations still available after processing over");                  return false;              }          }          if (annotations.isEmpty()) {              return false;          }          if (writerRoundDone) {              messager.printMessage(Diagnostic.Kind.ERROR, "Unexpected processing state: annotations still available after writing.");          }          collectSubscribers(annotations, env, messager);          checkForSubscribersToSkip(messager, indexPackage);          if (!methodsByClass.isEmpty()) {              createInfoIndexFile(index);          } else {              messager.printMessage(Diagnostic.Kind.WARNING, "No @Subscribe annotations found");          }          writerRoundDone = true;      } catch (RuntimeException e) {                  e.printStackTrace();          messager.printMessage(Diagnostic.Kind.ERROR, "Unexpected error in EventBusAnnotationProcessor: " + e);      }      return true;  }  private void collectSubscribers(Set<? extends TypeElement> annotations, RoundEnvironment env, Messager messager) {      for (TypeElement annotation : annotations) {          Set<? extends Element> elements = env.getElementsAnnotatedWith(annotation);          for (Element element : elements) {              if (element instanceof ExecutableElement) {                  ExecutableElement method = (ExecutableElement) element;                  if (checkHasNoErrors(method, messager)) {                      TypeElement classElement = (TypeElement) method.getEnclosingElement();                      methodsByClass.putElement(classElement, method);                  }              } else {                  messager.printMessage(Diagnostic.Kind.ERROR, "@Subscribe is only valid for methods", element);              }          }      }  }    private void checkForSubscribersToSkip(Messager messager, String myPackage) {      for (TypeElement skipCandidate : methodsByClass.keySet()) {          TypeElement subscriberClass = skipCandidate;          while (subscriberClass != null) {              if (!isVisible(myPackage, subscriberClass)) {                  boolean added = classesToSkip.add(skipCandidate);                  if (added) {                      String msg;                      if (subscriberClass.equals(skipCandidate)) {                          msg = "Falling back to reflection because class is not public";                      } else {                          msg = "Falling back to reflection because " + skipCandidate + " has a non-public super class";                      }                      messager.printMessage(Diagnostic.Kind.NOTE, msg, subscriberClass);                  }                  break;              }              List<ExecutableElement> methods = methodsByClass.get(subscriberClass);              if (methods != null) {                  for (ExecutableElement method : methods) {                      String skipReason =