 return null;      }  }  private void writeCreateSubscriberMethods(BufferedWriter writer, List<ExecutableElement> methods, String callPrefix, String myPackage) throws IOException {      for (ExecutableElement method : methods) {          List<? extends VariableElement> parameters = method.getParameters();          TypeMirror paramType = getParamTypeMirror(parameters.get(0), null);          TypeElement paramElement = (TypeElement) processingEnv.getTypeUtils().asElement(paramType);          String methodName = method.getSimpleName().toString();          String eventClass = getClassString(paramElement, myPackage) + ".class";          Subscribe subscribe = method.getAnnotation(Subscribe.class);          List<String> parts = new ArrayList<>();          parts.add(callPrefix + "("" + methodName + "",");          String lineEnd = "),";          if (subscribe.priority() == 0 && !subscribe.sticky()) {              if (subscribe.threadMode() == ThreadMode.POSTING) {                  parts.add(eventClass + lineEnd);              } else {                  parts.add(eventClass + ",");                  parts.add("ThreadMode." + subscribe.threadMode().name() + lineEnd);              }          } else {              parts.add(eventClass + ",");              parts.add("ThreadMode." + subscribe.threadMode().name() + ",");              parts.add(subscribe.priority() + ",");              parts.add(subscribe.sticky() + lineEnd);          }          writeLine(writer, 3, parts.toArray(new String[parts.size()]));          if (verbose) {              processingEnv.getMessager().printMessage(Diagnostic.Kind.NOTE, "Indexed @Subscribe at " + method.getEnclosingElement().getSimpleName() + "." + methodName + "(" + paramElement.getSimpleName() + ")");          }      }  }  private void createInfoIndexFile(String index) {      BufferedWriter writer = null;      try {          JavaFileObject sourceFile = processingEnv.getFiler().createSourceFile(index);          int period = index.lastIndexOf('.'); 