", args);      indent();      return this;  }    public Builder add(String format, Object... args) {      boolean hasRelative = false;      boolean hasIndexed = false;      int relativeParameterCount = 0;      int[] indexedParameterCount = new int[args.length];      for (int p = 0; p < format.length(); ) {          if (format.charAt(p) != '$') {              int nextP = format.indexOf('$', p + 1);              if (nextP == -1)                  nextP = format.length();              formatParts.add(format.substring(p, nextP));              p = nextP;              continue;          }                  p++;                  int indexStart = p;          char c;          do {              checkArgument(p < format.length(), "dangling format characters in '%s'", format);              c = format.charAt(p++);          } while (c >= '0' && c <= '9');          int indexEnd = p - 1;                  if (isNoArgPlaceholder(c)) {              checkArgument(indexStart == indexEnd, "$$, $>, $<, $[, $], $W, and $Z may not have an index");              formatParts.add("$" + c);              continue;          }                  int index;          if (indexStart < indexEnd) {              index = Integer.parseInt(format.substring(indexStart, indexEnd)) - 1;              hasIndexed = true;              if (args.length > 0) {                                  indexedParameterCount[index % args.length]++;              }          } else {              index = relativeParameterCount;              hasRelative = true;              relativeParameterCount++;          }          checkArgument(index >= 0 && index < args.length, "index %d for '%s' not in range (received %s arguments)", index + 1, format.substring(indexStart - 1, indexEnd + 1), args.length);          checkArgument(!hasIndexed || !hasRelative, "cannot mix indexed and positional parameters");          addArgument(format, c, args[index]);          formatParts.add("$" + c);      }      if (hasRelative) {          checkArgument(relative