hs.addAll(getClassPaths(classPath));      return this;  }  public JdepsConfiguration build() throws IOException {      ModuleFinder finder = systemModulePath;      if (upgradeModulePath != null) {          finder = ModuleFinder.compose(upgradeModulePath, systemModulePath);      }      if (appModulePath != null) {          finder = ModuleFinder.compose(finder, appModulePath);      }      if (!paths.isEmpty()) {          ModuleFinder otherModulePath = ModuleFinder.of(paths.toArray(new Path[0]));          finder = ModuleFinder.compose(finder, otherModulePath);                  otherModulePath.findAll().stream().map(mref -> mref.descriptor().name()).forEach(rootModules::add);      }          if (tokens.contains(ALL_SYSTEM) && rootModules.isEmpty() && initialArchives.isEmpty() && classPaths.isEmpty()) {          systemModulePath.findAll().stream().map(mref -> mref.descriptor().name()).forEach(rootModules::add);      }          if ((tokens.contains(ALL_MODULE_PATH)) && appModulePath != null) {          appModulePath.findAll().stream().map(mref -> mref.descriptor().name()).forEach(rootModules::add);      }          Set<String> mods = new HashSet<>(rootModules);          boolean unnamed = !initialArchives.isEmpty() || !classPaths.isEmpty();      if (tokens.contains(ALL_DEFAULT)) {          mods.addAll(systemModulePath.defaultSystemRoots());      } else if (tokens.contains(ALL_SYSTEM) || unnamed) {                  systemModulePath.findAll().stream().map(mref -> mref.descriptor().name()).forEach(mods::add);      }      if (unnamed && appModulePath != null) {                  appModulePath.findAll().stream().map(mref -> mref.descriptor().name()).forEach(mods::add);      }          Configuration config = Configuration.empty().resolve(finder, ModuleFinder.of(), mods);      return new JdepsConfiguration(config, systemModulePath, finder, rootModules, classPaths, initialArchives, version);  }  private static ModuleFinder createModulePathFinder(String mpaths) {      if (mpaths == null) {          return null;      } else {          String[] dirs = mpaths.split(File.pathSeparator);          Path[] paths = new Path[dirs.length];          int i = 0;          for (String dir : dirs) {              paths[i++] = Paths.get(dir);          }          return ModuleFinder.of(paths);      }  }    private List<Path> getClassPaths(String cpaths) {      if (cpaths.isEmpty()) {          return Collections.emptyList();      }      List<Path> paths = new ArrayList<>();      for (String p : cpaths.split(File.pathSeparator)) {          if (p.length() > 0) {                          int i = p.lastIndexOf(".*");              if (i > 0) {                  Path dir = Paths.get(p.substring(0, i));                  try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir, "*.jar")) {                      for (Path entry : stream) {                          paths.add(entry);                      }                  } catch (IOException e) {                      throw new UncheckedIOException(e);                  }              } else {                  paths.add(Paths.get(p));              }          }      }      return paths;  }  public Builder packages(Set<String> packageNames) {      this.targetPackages.addAll(packageNames);      return this;  }  public Builder regex(Pattern regex) {      this.regex = regex;      return this;  }  public Builder filter(Pattern regex) {      this.filterPattern = regex;      return this;  }  public Builder filter(boolean samePackage, boolean sameArchive) {      this.filterSamePackage = samePackage;      this.filterSameArchive = sameArchive;      return this;  }  public Builder requires(String name, Set<String> packageNames) {      this.requires.add(name);      this.targetPackages.addAll(packageNames);      return this;  }  public Builder findJDKInternals(boolean value) {      this.findJDKInterals = value;      return this;  }  public Builder findMissingDeps(boolean value) {      this.findMissingDeps = value;      return this;  }  public Builder includePattern(Pattern regex) {      this.includePattern = regex;      return this;  }  public JdepsFilter build() {      Dependency.Filter filter = null;      if (regex != null)          filter = Dependencies.getRegexFilter(regex);      else if (!targetPackages.isEmpty()) {          filter = Dependencies.getPackageFilter(targetPackages, false);      }      return new JdepsFilter(filter, filterPattern, filterSamePackage, filterSameArchive, findJDKInterals, findMissingDeps, includePattern, requires);  }  public Builder location(URI location) {      this.location = location;      return this;  }  public Builder classes(ClassFileReader reader) {      this.reader = reader;      return this;  }  public Module build() {      if (descriptor.isAutomatic() && isSystem) {          throw new InternalError("JDK module: " + name + " can't be automatic module");      }      Map<String, Set<String>> exports = new HashMap<>();      Map<String, Set<String>> opens = new HashMap<>();      if (descriptor.isAutomatic()) {                  descriptor.packages().forEach(pn -> exports.put(pn, Collections.emptySet()));          descriptor.packages().forEach(pn -> opens.put(pn, Collections.emptySet()));      } else {          descriptor.exports().stream().forEach(exp -> exports.computeIfAbsent(exp.source(), _k -> new HashSet<>()).addAll(exp.targets()));          descriptor.opens().stream().forEach(exp -> opens.computeIfAbsent(exp.source(), _k -> new HashSet<>()).addAll(exp.targets()));      }      return new Module(name, location, descriptor, exports, opens, isSystem, reader);  }  public Builder threadPool(Executor threadPool) {      this.threadPool = threadPool;      return this;  }  public Builder failureEventType(Class<?> failureEventType) {      this.failureEventType = failureEventType;      return this;  }  public Builder eventBus(EventBus eventBus) {      this.eventBus = eventBus;      return this;  }  public AsyncExecutor buildForScope(Object executionContext) {      if (eventBus == null) {          eventBus = EventBus.getDefault();      }      if (threadPool == null) {          threadPool = Executors.newCachedThreadPool();      }      if (failureEventType == null) {          failureEventType = ThrowableFailureEvent.class;      }      return new AsyncExecutor(threadPool, eventBus, failureEventType, executionContext);  }

@ParameterizedTest(name = "{0} bft node factory type")  @MethodSource("factoryFunctions")  public void validatorsArePaidBlockReward(final String testName, final BftAcceptanceTestParameterization nodeFactory) throws Exception {      setUp(testName, nodeFactory);      final String[] validators = { "validator" };      final BesuNode validator = nodeFactory.createNodeWithValidators(besu, "validator", validators);      final BesuNode nonValidator = nodeFactory.createNodeWithValidators(besu, "nonValidator", validators);      cluster.start(validator, nonValidator);      final Account validator1Account = Account.create(ethTransactions, validator.getAddress());      final int blockRewardEth = 5;      final int blockToCheck = 2;      cluster.verify(validator1Account.balanceAtBlockEquals(Amount.ether(0), BigInteger.ZERO));      cluster.verify(validator1Account.balanceAtBlockEquals(Amount.ether(blockRewardEth * blockToCheck), BigInteger.valueOf(blockToCheck)));  }  @ParameterizedTest(name = "{0} bft node factory type")  @MethodSource("factoryFunctions")  public void payBlockRewardToConfiguredNode(final String testName, final BftAcceptanceTestParameterization nodeFactory) throws Exception {      setUp(testName, nodeFactory);      final String[] validators = { "validator1" };      final BesuNode validator1 = nodeFactory.createNodeWithValidators(besu, "validator1", validators);      final Optional<String> initialConfig = validator1.getGenesisConfigProvider().create(singletonList(validator1));      if (initialConfig.isEmpty()) {          throw new RuntimeException("Unable to generate genesis config.");      }      final String miningBeneficiaryAddress = "0x1234567890123456789012345678901234567890";      final Account miningBeneficiaryAccount = Account.create(ethTransactions, Address.fromHexString(miningBeneficiaryAddress));      final String bftOptions = formatKeyValues("miningbeneficiary", miningBeneficiaryAddress);      final String configWithMiningBeneficiary = configureBftOptions(initialConfig.get(), bftOptions);      validator1.setGenesisConfig(configWithMiningBeneficiary);      cluster.start(validator1);      final int blockRewardEth = 5;      final int blockToCheck = 2;      cluster.verify(miningBeneficiaryAccount.balanceAtBlockEquals(Amount.ether(0), BigInteger.ZERO));      cluster.verify(miningBeneficiaryAccount.balanceAtBlockEquals(Amount.ether(blockRewardEth * blockToCheck), BigInteger.valueOf(blockToCheck)));  }  @ParameterizedTest(name = "{0} bft node factory type")  @MethodSource("factoryFunctions")  public void payBlockRewardAccordingToTransitions_defaultInitialMiningBeneficiary(final String testName, final BftAcceptanceTestParameterization nodeFactory) throws Exception {      setUp(testName, nodeFactory);      final List<Address> addresses = generateAddresses(2);      final Map<Long, Optional<Address>> transitions = Map.of(2L, Optional.of(addresses.get(0)), 3L, Optional.of(addresses.get(1)), 6L, Optional.empty(), 8L, Optional.of(addresses.get(0)));      testMiningBeneficiaryTransitions(Optional.empty(), transitions);  }  @ParameterizedTest(name = "{0} bft node factory type")  @MethodSource("factoryFunctions")  public void payBlockRewardAccordingToTransitions_customInitialMiningBeneficiary(final String testName, final BftAcceptanceTestParameterization nodeFactory) throws Exception {      setUp(testName, nodeFactory);      final List<Address> addresses = generateAddresses(4);      final Map<Long, Optional<Address>> transitions = Map.of(1L, Optional.of(addresses.get(1)), 2L, Optional.of(addresses.get(2)), 3L, Optional.of(addresses.get(3)), 4L, Optional.empty());      testMiningBeneficiaryTransitions(Optional.of(addresses.get(0)), transitions);  }  private void testMiningBeneficiaryTransitions(final Optional<Address> initialMiningBeneficiary, final Map<Long, Optional<Address>> miningBeneficiaryTransitions) throws Exception {      final String[] validators = { "validator1" };      final BesuNode validator1 = nodeFactory.createNodeWithValidators(besu, "validator1", validators);      final Optional<String> initialConfig = validator1.getGenesisConfigProvider().create(singletonList(validator1));      if (initialConfig.isEmpty()) {          throw new RuntimeException("Unable to generate genesis config.");      }      final String miningBeneficiary = initialMiningBeneficiary.map(Address::toHexString).orElse("");      final String bftOptions = formatKeyValues("miningbeneficiary", miningBeneficiary);      final String configWithMiningBeneficiary = configureBftOptions(initialConfig.get(), bftOptions, miningBeneficiaryTransitions);      validator1.setGenesisConfig(configWithMiningBeneficiary);      cluster.start(validator1);          final NavigableMap<Long, Optional<Address>> orderedTransitions = new TreeMap<>(miningBeneficiaryTransitions);      final long lastConfiguredBlock = orderedTransitions.lastKey();      final Map<Address, Amount> accountBalances = new HashMap<>();      for (long i = 1; i < lastConfiguredBlock + 2; i++) {          final Address beneficiaryAddress = Optional.ofNullable(orderedTransitions.floorEntry(i)).flatMap(Entry::getValue).orElse(validator1.getAddress());          final Account beneficiary = Account.create(ethTransactions, beneficiaryAddress);          final Amount currentBalance = accountBalances.computeIfAbsent(beneficiaryAddress, __ -> Amount.wei(BigInteger.ZERO));          cluster.verify(beneficiary.balanceAtBlockEquals(currentBalance, BigInteger.valueOf(i - 1)));          final Amount newBalance = currentBalance.add(BLOCK_REWARD);          cluster.verify(beneficiary.balanceAtBlockEquals(newBalance, BigInteger.valueOf(i)));          accountBalances.put(beneficiaryAddress, newBalance);      }  }  private String configureBftOptions(final String originalOptions, final String bftOptions) {      return configureBftOptions(originalOptions, bftOptions, Collections.emptyMap());  }  private String configureBftOptions(final String originalOptions, final String bftOptions, final Map<Long, Optional<Address>> transitions) {      final StringBuilder stringBuilder = new StringBuilder().append(formatBftTransitionsOptions(transitions)).append(",
").append(quote(bftType)).append(": {").append(bftOptions).append(",");      return originalOptions.replace(quote(bftType) + ": {", stringBuilder.toString());  }  private String formatBftTransitionsOptions(final Map<Long, Optional<Address>> transitions) {      final StringBuilder stringBuilder = new StringBuilder();      stringBuilder.append(quote("transitions"));      stringBuilder.append(": {
");      stringBuilder.append(quote(bftType));      stringBuilder.append(": [");      boolean isFirst = true;      for (Long blockNumber : transitions.keySet()) {          if (!isFirst) {              stringBuilder.append(",");          }          isFirst = false;          final Optional<Address> miningBeneficiary = transitions.get(blockNumber);          stringBuilder.append("
");          stringBuilder.append(formatTransition(blockNumber, miningBeneficiary));      }      stringBuilder.append("
]");      stringBuilder.append("}
");      return stringBuilder.toString();  }  private List<Address> generateAddresses(final int count) {      final List<Address> addresses = new ArrayList<>();      for (int i = 0; i < count; i++) {          addresses.add(Address.fromHexString(Integer.toString(i + 1, 16)));      }      return addresses;  }  private String formatKeyValues(final Object... keyOrValue) {      if (keyOrValue.length % 2 == 1) {                  throw new IllegalArgumentException("Must supply key-value pairs");      }      final StringBuilder stringBuilder = new StringBuilder();      for (int i = 0; i < keyOrValue.length; i += 2) {          if (i > 0) {              stringBuilder.append(", ");          }          final String key = keyOrValue[i].toString();          final Object value = keyOrValue[i + 1];          final String valueStr = value instanceof String ? quote(value) : value.toString();          stringBuilder.append(String.format("
%s: %s", quote(key), valueStr));      }      return stringBuilder.toString();  }  private String quote(final Object value) {      return '"' + value.toString() + '"';  }  private String formatTransition(final long blockNumber, final Optional<Address> miningBeneficiary) {      final StringBuilder stringBuilder = new StringBuilder();      stringBuilder.append("{");      stringBuilder.append(formatKeyValues("block", blockNumber, "miningbeneficiary", miningBeneficiary.map(Address::toHexString).orElse("")));      stringBuilder.append("}");      return stringBuilder.toString();  }

@Test  public void shouldMineTransactionsOnSingleNode() throws IOException {      final BesuNode minerNode = besu.createCliqueNode("miner1");      cluster.start(minerNode);      final Account sender = accounts.createAccount("account1");      final Account receiver = accounts.createAccount("account2");      minerNode.execute(accountTransactions.createTransfer(sender, 50));      cluster.verify(sender.balanceEquals(50));      minerNode.execute(accountTransactions.createIncrementalTransfers(sender, receiver, 1));      cluster.verify(receiver.balanceEquals(1));      minerNode.execute(accountTransactions.createIncrementalTransfers(sender, receiver, 2));      cluster.verify(receiver.balanceEquals(3));  }  @Test  public void shouldNotMineBlocksIfNoTransactionsWhenCreateEmptyBlockIsFalse() throws IOException {      final var cliqueOptionsNoEmptyBlocks = new CliqueOptions(CliqueOptions.DEFAULT.blockPeriodSeconds(), CliqueOptions.DEFAULT.epochLength(), false);      final BesuNode minerNode = besu.createCliqueNode("miner1", cliqueOptionsNoEmptyBlocks);      cluster.start(minerNode);      cluster.verify(clique.noNewBlockCreated(minerNode));  }  @Test  public void shouldMineBlocksOnlyWhenTransactionsArePresentWhenCreateEmptyBlocksIsFalse() throws IOException {      final var cliqueOptionsNoEmptyBlocks = new CliqueOptions(CliqueOptions.DEFAULT.blockPeriodSeconds(), CliqueOptions.DEFAULT.epochLength(), false);      final BesuNode minerNode = besu.createCliqueNode("miner1", cliqueOptionsNoEmptyBlocks);      cluster.start(minerNode);      final Account sender = accounts.createAccount("account1");      cluster.verify(clique.noNewBlockCreated(minerNode));      minerNode.execute(accountTransactions.createTransfer(sender, 50));      minerNode.verify(clique.blockIsCreatedByProposer(minerNode));  }  @Test  @Disabled("flaky see https:public void shouldMineTransactionsOnMultipleNodes() throws IOException {      final BesuNode minerNode1 = besu.createCliqueNode("miner1");      final BesuNode minerNode2 = besu.createCliqueNode("miner2");      final BesuNode minerNode3 = besu.createCliqueNode("miner3");      startClusterAndVerifyProducingBlocks(minerNode1, minerNode2, minerNode3);      final Account sender = accounts.createAccount("account1");      final Account receiver = accounts.createAccount("account2");      minerNode1.execute(accountTransactions.createTransfer(sender, 50));      cluster.verify(sender.balanceEquals(50));      minerNode2.execute(accountTransactions.createIncrementalTransfers(sender, receiver, 1));      cluster.verify(receiver.balanceEquals(1));      minerNode3.execute(accountTransactions.createIncrementalTransfers(sender, receiver, 2));      cluster.verify(receiver.balanceEquals(3));  }  @Test  public void shouldStallMiningWhenInsufficientValidators() throws IOException {      final BesuNode minerNode1 = besu.createCliqueNode("miner1");      final BesuNode minerNode2 = besu.createCliqueNode("miner2");      final BesuNode minerNode3 = besu.createCliqueNode("miner3");      startClusterAndVerifyProducingBlocks(minerNode1, minerNode2, minerNode3);      cluster.stopNode(minerNode2);      cluster.stopNode(minerNode3);      minerNode1.verify(net.awaitPeerCount(0));      minerNode1.verify(clique.blockIsCreatedByProposer(minerNode1));      minerNode1.verify(clique.noNewBlockCreated(minerNode1));  }  private void startClusterAndVerifyProducingBlocks(final BesuNode minerNode1, final BesuNode minerNode2, final BesuNode minerNode3) {      cluster.start(minerNode1, minerNode2, minerNode3);          minerNode1.verify(net.awaitPeerCount(2));      minerNode2.verify(net.awaitPeerCount(2));      minerNode3.verify(net.awaitPeerCount(2));          waitForBlockHeight(minerNode1, 1);      final var minerChainHead = minerNode1.execute(ethTransactions.block());      minerNode2.verify(blockchain.minimumHeight(minerChainHead.getNumber().longValue()));      minerNode3.verify(blockchain.minimumHeight(minerChainHead.getNumber().longValue()));  }  @Test  @Disabled("flaky see https:public void shouldStillMineWhenANodeFailsAndHasSufficientValidators() throws IOException {      final BesuNode minerNode1 = besu.createCliqueNode("miner1");      final BesuNode minerNode2 = besu.createCliqueNode("miner2");      final BesuNode minerNode3 = besu.createCliqueNode("miner3");      startClusterAndVerifyProducingBlocks(minerNode1, minerNode2, minerNode3);      cluster.verifyOnActiveNodes(blockchain.reachesHeight(minerNode1, 1, 85));      cluster.stopNode(minerNode3);      cluster.verifyOnActiveNodes(net.awaitPeerCount(1));      cluster.verifyOnActiveNodes(blockchain.reachesHeight(minerNode1, 2));      cluster.verifyOnActiveNodes(clique.blockIsCreatedByProposer(minerNode1));      cluster.verifyOnActiveNodes(clique.blockIsCreatedByProposer(minerNode2));  }  @Test  public void shouldMineBlocksAccordingToBlockPeriodTransitions() throws IOException {      final var cliqueOptions = new CliqueOptions(3, CliqueOptions.DEFAULT.epochLength(), true);      final BesuNode minerNode = besu.createCliqueNode("miner1", cliqueOptions);          final Map<String, Object> decreasePeriodTo2_Transition = Map.of("block", 3, "blockperiodseconds", 2);      final Map<String, Object> decreasePeriodTo1_Transition = Map.of("block", 4, "blockperiodseconds", 1);          final Map<String, Object> dummy_Transition = Map.of("block", 5, "createemptyblocks", true);      final Map<String, Object> increasePeriodTo2_Transition = Map.of("block", 6, "blockperiodseconds", 2);      final Optional<String> initialGenesis = minerNode.getGenesisConfigProvider().create(List.of(minerNode));      final String genesisWithTransitions = prependTransitionsToCliqueOptions(initialGenesis.orElseThrow(), List.of(decreasePeriodTo2_Transition, decreasePeriodTo1_Transition, dummy_Transition, increasePeriodTo2_Transition));      minerNode.setGenesisConfig(genesisWithTransitions);          cluster.start(minerNode);      minerNode.verify(blockchain.reachesHeight(minerNode, 5));          final long block1Timestamp = getTimestampForBlock(minerNode, 1);      final long block2Timestamp = getTimestampForBlock(minerNode, 2);      final long block3Timestamp = getTimestampForBlock(minerNode, 3);      final long block4Timestamp = getTimestampForBlock(minerNode, 4);      final long block5Timestamp = getTimestampForBlock(minerNode, 5);      final long block6Timestamp = getTimestampForBlock(minerNode, 6);      assertThat(block2Timestamp - block1Timestamp).isCloseTo(3, withPercentage(20));      assertThat(block3Timestamp - block2Timestamp).isCloseTo(2, withPercentage(20));      assertThat(block4Timestamp - block3Timestamp).isCloseTo(1, withPercentage(20));      assertThat(block5Timestamp - block4Timestamp).isCloseTo(1, withPercentage(20));      assertThat(block6Timestamp - block5Timestamp).isCloseTo(2, withPercentage(20));  }  @Test  public void shouldMineBlocksAccordingToCreateEmptyBlocksTransitions() throws IOException {      final var cliqueOptionsEmptyBlocks = new CliqueOptions(2, CliqueOptions.DEFAULT.epochLength(), true);      final BesuNode minerNode = besu.createCliqueNode("miner1", cliqueOptionsEmptyBlocks);          final Map<String, Object> noEmptyBlocks_Transition = Map.of("block", 3, "createemptyblocks", false);      final Map<String, Object> emptyBlocks_Transition = Map.of("block", 4, "createemptyblocks", true);      final Map<String, Object> secondNoEmptyBlocks_Transition = Map.of("block", 6, "createemptyblocks", false);          final Map<String, Object> dummy_Transition = Map.of("block", 7, "blockperiodseconds", 1);      final Optional<String> initialGenesis = minerNode.getGenesisConfigProvider().create(List.of(minerNode));      final String genesisWithTransitions = prependTransitionsToCliqueOptions(initialGenesis.orElseThrow(), List.of(noEmptyBlocks_Transition, emptyBlocks_Transition, secondNoEmptyBlocks_Transition, dummy_Transition));      minerNode.setGenesisConfig(genesisWithTransitions);      final Account sender = accounts.createAccount("account1");          cluster.start(minerNode);      minerNode.verify(blockchain.reachesHeight(minerNode, 1));          cluster.verify(clique.noNewBlockCreated(minerNode));      minerNode.execute(accountTransactions.createTransfer(sender, 50));      minerNode.verify(clique.blockIsCreatedByProposer(minerNode));          minerNode.verify(blockchain.reachesHeight(minerNode, 2));          cluster.verify(clique.noNewBlockCreated(minerNode));      minerNode.execute(accountTransactions.createTransfer(sender, 50));      minerNode.verify(clique.blockIsCreatedByProposer(minerNode));          cluster.verify(clique.noNewBlockCreated(minerNode));  }  private long getTimestampForBlock(final BesuNode minerNode, final int blockNumber) {      return minerNode.execute(ethTransactions.block(DefaultBlockParameter.valueOf(BigInteger.valueOf(blockNumber)))).getTimestamp().longValue();  }  private String prependTransitionsToCliqueOptions(final String originalOptions, final List<Map<String, Object>> transitions) {      final StringBuilder stringBuilder = new StringBuilder().append(formatCliqueTransitionsOptions(transitions)).append(",
").append(quote("clique")).append(": {");      return originalOptions.replace(quote("clique") + ": {", stringBuilder.toString());  }  private String formatCliqueTransitionsOptions(final List<Map<String, Object>> transitions) {      final StringBuilder stringBuilder = new StringBuilder();      stringBuilder.append(quote("transitions"));      stringBuilder.append(": {
");      stringBuilder.append(quote("clique"));      stringBuilder.append(": [");      final String formattedTransitions = transitions.stream().map(this::formatTransition).collect(joining(",
"));      stringBuilder.append(formattedTransitions);      stringBuilder.append("
]");      stringBuilder.append("}
");      return stringBuilder.toString();  }  private String quote(final Object value) {      return '"' + value.toString() + '"';  }  private String formatTransition(final Map<String, Object> transition) {      final StringBuilder stringBuilder = new StringBuilder();      stringBuilder.append("{");      String formattedTransition = transition.keySet().stream().map(key -> formatKeyValues(key, transition.get(key))).collect(joining(","));      stringBuilder.append(formattedTransition);      stringBuilder.append("}");      return stringBuilder.toString();  }  private String formatKeyValues(final Object... keyOrValue) {      if (keyOrValue.length % 2 == 1) {                  throw new IllegalArgumentException("Must supply key-value pairs");      }      final StringBuilder stringBuilder = new StringBuilder();      for (int i = 0; i < keyOrValue.length; i += 2) {          if (i > 0) {              stringBuilder.append(", ");          }          final String key = keyOrValue[i].toString();          final Object value = keyOrValue[i + 1];          final String valueStr = value instanceof String ? quote(value) : value.toString();          stringBuilder.append(String.format("
%s: %s", quote(key), valueStr));      }      return stringBuilder.toString();  }

