" + "          "0xc4c3a3f99b26e5e534b71d6f33ca6ea5c174decfb16dd7237c60eff9774ef4a3": "0x6f8a80d14311c39f35f516fa664deaaaa13e85b2f7493f37f6144d86991ec012"" + "        }" + "    }" + "  }" + "}");      final Map<Address, GenesisAccount> allocations = config.streamAllocations().collect(Collectors.toMap(GenesisAccount::address, Function.identity()));      assertThat(allocations.keySet()).map(Address::toUnprefixedHexString).containsOnly("fe3b557e8fb62b89f4916b721be55ceb828dbd73", "627306090abab3a6e1400e9345bc60c78a8bef57", "f17f52151ebef6c7334fad080c5704d77216b732");      final GenesisAccount alloc1 = allocations.get(Address.fromHexString("fe3b557e8fb62b89f4916b721be55ceb828dbd73"));      final GenesisAccount alloc2 = allocations.get(Address.fromHexString("627306090abab3a6e1400e9345bc60c78a8bef57"));      final GenesisAccount alloc3 = allocations.get(Address.fromHexString("f17f52151ebef6c7334fad080c5704d77216b732"));      assertThat(alloc1.balance()).isEqualTo(GenesisReader.ParserUtils.parseBalance("0xad78ebc5ac6200000"));      assertThat(alloc2.balance()).isEqualTo(GenesisReader.ParserUtils.parseBalance("1000"));      assertThat(alloc3.balance()).isEqualTo(GenesisReader.ParserUtils.parseBalance("90000000000000000000000"));      assertThat(alloc3.storage()).hasSize(2);      assertThat(alloc3.storage()).containsEntry(UInt256.fromHexString("0xc4c3a3f99b26e5e534b71d6f33ca6ea5c174decfb16dd7237c60eff9774ef4a4"), UInt256.fromHexString("0x937307647bd3b9a82abe2974e1407241d54947bbb39763a4cac9f77166ad92a0"));      assertThat(alloc3.storage()).containsEntry(UInt256.fromHexString("0xc4c3a3f99b26e5e534b71d6f33ca6ea5c174decfb16dd7237c60eff9774ef4a3"), UInt256.fromHexString("0x6f8a80d14311c39f35f516fa664deaaaa13e85b2f7493f37f6144d86991ec012"));  }  @Test  void shouldGetEmptyAllocationsWhenAllocNotPresent() {      final GenesisConfig config = fromConfig("{}");      assertThat(config.streamAllocations()).isEmpty();  }  @Test  void shouldGetLargeChainId() {      final GenesisConfig config