}  @Test  void testOverridePresent() {      final GenesisConfig config = GenesisConfig.fromResource("/dev.json");      final int bigBlock = 999_999_999;      final String bigBlockString = Integer.toString(bigBlock);      final Map<String, String> override = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);      override.put("istanbulBlock", bigBlockString);      override.put("chainId", bigBlockString);      override.put("contractSizeLimit", bigBlockString);      assertThat(config.getForkBlockNumbers()).isNotEmpty();      assertThat(config.withOverrides(override).getConfigOptions().getIstanbulBlockNumber()).hasValue(bigBlock);      assertThat(config.withOverrides(override).getConfigOptions().getChainId()).hasValue(BigInteger.valueOf(bigBlock));      assertThat(config.withOverrides(override).getConfigOptions().getContractSizeLimit()).hasValue(bigBlock);  }  @Test  void testOverrideNull() {      final GenesisConfig config = GenesisConfig.fromResource("/dev.json");      final Map<String, String> override = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);      override.put("istanbulBlock", null);      override.put("chainId", null);      override.put("contractSizeLimit", null);      assertThat(config.getForkBlockNumbers()).isNotEmpty();      assertThat(config.withOverrides(override).getConfigOptions().getIstanbulBlockNumber()).isNotPresent();      assertThat(config.withOverrides(override).getConfigOptions().getChainId()).isNotPresent();      assertThat(config.withOverrides(override).getConfigOptions().getContractSizeLimit()).isNotPresent();  }  @Test  void testOverrideCaseInsensitivity() {      final GenesisConfig config = GenesisConfig.fromResource("/dev.json");      final int bigBlock = 999_999_999;      final String bigBlockString = Integer.toString(bigBlock);      final Map<String, String> override = new HashMap<>();          override.put("istanbulBlock", bigBlockString);          override.put("CHAINID", bigBlockString);          override.put("contractsizelimit", bigBlockString);      assertThat(config.withOverrides(override).getConfigOptions().getIstanbulBlockNumber()).hasValue(bigBlock);      assertThat(config.withOverrides(override).getConfigOptions().getChainId()).hasValue(BigInteger.valueOf(bigBlock));      assertThat(config.withOverrides(override).getConfigOptions().getContractSizeLimit()).hasValue(bigBlock);  }  @Test  void testOverrideEmptyString() {      final GenesisConfig config = GenesisConfig.fromResource("/dev.json");      final Map<String, String> override = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);      override.put("istanbulBlock", "");      override.put("chainId", "");      override.put("contractSizeLimit", "");      assertThat(config.withOverrides(override).getConfigOptions().getIstanbulBlockNumber()).isNotPresent();      assertThat(config.withOverrides(override).getConfigOptions().getChainId()).isNotPresent();      assertThat(config.withOverrides(override).getConfigOptions().getContractSizeLimit()).isNotPresent();  }  @Test  void testNoOverride() {      final GenesisConfig config = GenesisConfig.fromResource("/dev.json");      assertThat(config.getConfigOptions().getLondonBlockNumber()).hasValue(0);      assertThat(config.getConfigOptions().getIstanbulBlockNumber()).isNotPresent();      assertThat(config.getConfigOptions().getChainId()).hasValue(BigInteger.valueOf(1337));      assertThat(config.getConfigOptions().getContractSizeLimit()).hasValue(2147483647);      assertThat(config.getConfigOptions().getEvmStackSize()).isNotPresent();      assertThat(config.getConfigOptions().getEcip1017EraRounds()).isNotPresent();  }  @Test  void testConstantinopleFixShouldNotBeSupportedAlongPetersburg() {          final GenesisConfig config = GenesisConfig.fromResource("/all_forks.json");      assertThat(config.getConfigOptions().getPetersburgBlockNumber()).hasValue(7);          final Map<String, String> override = new HashMap<>();      override.put("constantinopleFixBlock", "1000");      assertThatExceptionOfType(RuntimeException.class).isThrownBy(() -> config.withOverrides(override).getConfigOptions().getPetersburgBlockNumber()).withMessage("Genesis files cannot specify both petersburgBlock and constantinopleFixBlock.");  }  @Test  void shouldLoadForksInSortedOrder() throws IOException {      final ObjectNode configNode = new ObjectMapper().createObjectNode().set("config", JsonUtil.objectNodeFromString(Resources.toString(Resources.getResource(    "valid_config_with_custom_forks.json"), StandardCharsets.UTF_8)));      final GenesisConfig config = fromConfig(configNode);      assertThat(config.getForkBlockNumbers()).containsExactly(1L, 2L, 3L, 1035301L, 2222222L);      assertThat(config.getConfigOptions().getChainId()).hasValue(BigInteger.valueOf(4));  }  @Test  void shouldLoadForksIgnoreClassicForkBlock() throws IOException {      final ObjectNode configNode = new ObjectMapper().createObjectNode().set("config", JsonUtil.objectNodeFromString(Resources.toString(Resources.getResource(    "valid_config_with_etc_forks.json"), StandardCharsets.UTF_8)));      final GenesisConfig config = fromConfig(configNode);      assertThat(config.getForkBlockNumbers()).containsExactly(1L, 2L, 3L, 1035301L);      assertThat(config.getConfigOptions().getChainId()).hasValue(BigInteger.valueOf(61));  }  @Test  void shouldLoadForksIgnoreUnexpectedValues() throws IOException {      final ObjectNode configNoUnexpectedForks = new ObjectMapper().createObjectNode().set("config", JsonUtil.objectNodeFromString(Resources.toString(Resources.getResource("valid_config.json"), StandardCharsets.UTF_8)));      final ObjectNode configClassicFork = new ObjectMapper().createObjectNode().set("config", JsonUtil.objectNodeFromString(Resources.toString(Resources.getResource(    "valid_config_with_etc_forks.json"), StandardCharsets.UTF_8)));      final ObjectNode configMultipleUnexpectedForks = new ObjectMapper().createObjectNode().set("config", JsonUtil.objectNodeFromString(Resources.toString(Resources.getResource(    "valid_config_with_unexpected_forks.json"), StandardCharsets.UTF_8)));      final GenesisConfig configFileNoUnexpectedForks = fromConfig(configNoUnexpectedForks);      final GenesisConfig configFileClassicFork = fromConfig(configClassicFork);      final GenesisConfig configFileMultipleUnexpectedForks = fromConfig(configMultipleUnexpectedForks);      assertThat(configFileNoUnexpectedForks.getForkBlockNumbers()).containsExactly(1L, 2L, 3L, 1035301L);      assertThat(configFileNoUnexpectedForks.getForkBlockNumbers()).isEqualTo(configFileClassicFork.getForkBlockNumbers());      assertThat(configFileNoUnexpectedForks.getForkBlockNumbers()).isEqualTo(configFileMultipleUnexpectedForks.getForkBlockNumbers());      assertThat(configFileNoUnexpectedForks.getConfigOptions().getChainId()).hasValue(BigInteger.valueOf(61));  }    @Test  void roundTripForkIdBlocks() throws IOException {      final String configText = Resources.toString(Resources.getResource("all_forks.json"), StandardCharsets.UTF_8);      final ObjectNode genesisNode = JsonUtil.objectNodeFromString(configText);      final GenesisConfig genesisConfig = fromConfig(genesisNode);      final ObjectNode output = JsonUtil.objectNodeFromMap(genesisConfig.getConfigOptions().asMap());      assertThat(JsonUtil.getJson(output, true)).isEqualTo(JsonUtil.getJson(genesisNode.get("config"), true));  }  private GenesisConfig configWithProperty(final String key, final String value) {      return fromConfig("{"" + key + "":"" + value + ""}");  }  private void assertInvalidConfiguration(final ThrowingCallable getter) {      assertThatThrownBy(getter).isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Invalid genesis block configuration");  }

