" + ""eip150Block": 2,
" + ""eip158Block": 3,
" + ""byzantiumBlock": 1035301}" + "}";      final GenesisConfigOptions config = GenesisConfig.fromConfig(jsonInput).getConfigOptions();      final ProtocolSchedule protocolSchedule = CliqueProtocolSchedule.create(config, new ForksSchedule<>(List.of()), NODE_KEY, false, EvmConfiguration.DEFAULT, MiningConfiguration.MINING_DISABLED, new BadBlockManager(), false, false, new NoOpMetricsSystem());      final ProtocolSpec homesteadSpec = protocolSchedule.getByBlockHeader(blockHeader(1));      final ProtocolSpec tangerineWhistleSpec = protocolSchedule.getByBlockHeader(blockHeader(2));      final ProtocolSpec spuriousDragonSpec = protocolSchedule.getByBlockHeader(blockHeader(3));      final ProtocolSpec byzantiumSpec = protocolSchedule.getByBlockHeader(blockHeader(1035301));      assertThat(homesteadSpec.equals(tangerineWhistleSpec)).isFalse();      assertThat(tangerineWhistleSpec.equals(spuriousDragonSpec)).isFalse();      assertThat(spuriousDragonSpec.equals(byzantiumSpec)).isFalse();  }  @Test  public void parametersAlignWithMainnetWithAdjustments() {      final ForksSchedule<CliqueConfigOptions> forksSchedule = new ForksSchedule<>(List.of(new ForkSpec<>(0, JsonCliqueConfigOptions.DEFAULT)));      final ProtocolSpec homestead = CliqueProtocolSchedule.create(GenesisConfig.DEFAULT.getConfigOptions(), forksSchedule, NODE_KEY, false, EvmConfiguration.DEFAULT, MiningConfiguration.MINING_DISABLED, new BadBlockManager(), false, false, new NoOpMetricsSystem()).getByBlockHeader(blockHeader(0));      assertThat(homestead.getHardforkId()).isEqualTo(FRONTIER);      assertThat(homestead.getBlockReward()).isEqualTo(Wei.ZERO);      assertThat(homestead.isSkipZeroBlockRewards()).isEqualTo(true);      assertThat(homestead.getDifficultyCalculator()).isInstanceOf(CliqueDifficultyCalculator.class);  }  @Test  public void zeroEpochLengthThrowsException() {      final CliqueConfigOptions cliqueOptions = mock(JsonCliqueConfigOptions.class);      when(cliqueOptions.getEpochLength()).thenReturn(0L);      when(genesisConfig.getCliqueConfigOptions()).thenReturn(cliqueOptions);      assertThatThrownBy(() -> CliqueProtocolSchedule.create(genesisConfig, new ForksSchedule<>(List.of()), NODE_KEY, false, EvmConfiguration.DEFAULT, MiningConfiguration.MINING_DISABLED, new BadBlockManager(), false, false, new NoOpMetricsSystem())).isInstanceOf(IllegalArgumentException.class).hasMessage("Epoch length in config must be greater than zero");  }  @Test  public void negativeEpochLengthThrowsException() {      final CliqueConfigOptions cliqueOptions = mock(JsonCliqueConfigOptions.class);      when(cliqueOptions.getEpochLength()).thenReturn(-3000L);      when(genesisConfig.getCliqueConfigOptions()).thenReturn(cliqueOptions);      assertThatThrownBy(() -> CliqueProtocolSchedule.create(genesisConfig, new ForksSchedule<>(List.of()), NODE_KEY, false, EvmConfiguration.DEFAULT, MiningConfiguration.MINING_DISABLED, new BadBlockManager(), false, false, new NoOpMetricsSystem())).isInstanceOf(IllegalArgumentException.class).hasMessage("Epoch length in config must be greater than zero");  }  @Test  public void shouldValidateBaseFeeMarketTransition() {      final BlockHeaderTestFixture headerBuilder = new BlockHeaderTestFixture();      final String jsonInput = "{"config": " + "	{"chainId": 1337,
" + "	"londonBlock": 2}
" + "}";      final GenesisConfigOptions config = GenesisConfig.fromConfig(jsonInput).getConfigOptions();      final ForksSchedule<CliqueConfigOptions> forksSchedule = new ForksSchedule<>(List.of(new ForkSpec<>(0, JsonCliqueConfigOptions.DEFAULT)));      final ProtocolSchedule protocolSchedule = CliqueProtocolSchedule.create(config, forksSchedule, NODE_KEY, false, EvmConfiguration.DEFAULT, MiningConfiguration.MINING_DISABLED, new BadBlockManager(), false, false, new NoOpMetricsSystem());      BlockHeader emptyFrontierParent = headerBuilder.number(0).mixHash(Hash.fromHexStringLenient("0x0")).gasLimit(5000L).timestamp(Instant.now().getEpochSecond() - 30L).buildHeader();          BlockHeader emptyFrontierBlock1 = headerBuilder.number(1).timestamp(Instant.now().getEpochSecond() - 15L).parentHash(emptyFrontierParent.getHash()).buildHeader();          BlockHeader emptyLondonBlock1 = headerBuilder.baseFeePerGas(Wei.of(1000000000L)).gasLimit(10000L).buildHeader();          BlockHeader emptyLondonBlock2 = headerBuilder.number(2).timestamp(Instant.now().getEpochSecond()).parentHash(emptyFrontierBlock1.getHash()).buildHeader();          assertThat(validateHeaderByProtocolSchedule(protocolSchedule, emptyFrontierBlock1, emptyFrontierParent)).isTrue();          assertThat(validateHeaderByProtocolSchedule(protocolSchedule, emptyLondonBlock1, emptyFrontierParent)).isFalse();          assertThat(validateHeaderByProtocolSchedule(protocolSchedule, emptyLondonBlock2, emptyFrontierBlock1)).isTrue();  }  private boolean validateHeaderByProtocolSchedule(final ProtocolSchedule schedule, final BlockHeader blockHeader, final BlockHeader parentBlockHeader) {      return schedule.getByBlockHeader(blockHeader).getBlockHeaderValidator().validateHeader(blockHeader, parentBlockHeader, null, HeaderValidationMode.LIGHT);  }  private BlockHeader blockHeader(final long number) {      return new BlockHeaderTestFixture().number(number).buildHeader();  }
